-- Seeds 55 Kajkavian dictionary entries from published dictionaries (Kajkaviana, OŠ Jakovlje, Rječnik hrvatskoga kajkavskoga književnog jezika).
-- All are placeholder entries without places: the app shows them for the whole region until editors add usages.
-- Additive and idempotent: existing ids are never overwritten, except the three original samples (hiza, kaj, denes),
-- which are replaced only while still untouched (placeholder, still carrying the original "sample" source, no linked submission).
-- Ids are ASCII; headwords and forms keep their diacritics.
insert into public.heritage_words (id, entry, areas, active) values ('hiza', '{"id":"hiza","headword":"hiža","meaning":{"hr":"kuća, dom"},"partOfSpeech":"imenica","variants":[{"id":"hiza-v1","form":"hiža","status":"placeholder","usages":[]}],"tags":["dom","svakodnevica"],"status":"placeholder","sources":[{"id":"src-kajkaviana","kind":"publication","credit":"Kajkavski rječnik – Kajkaviana"}]}'::jsonb, '[]'::jsonb, true)
  on conflict (id) do update set entry = excluded.entry, areas = excluded.areas, active = excluded.active
  where public.heritage_words.submission_id is null
    and public.heritage_words.entry->>'status' = 'placeholder'
    and public.heritage_words.entry->'sources'->0->>'id' = 'sample';
